          ...JSON.parse(String(options.body)),
          updatedAt: "2026-09-06T12:00:00Z",
        },
        {
          headers: {
            ETag: '"availability:6c5dbd10-9ad5-4000-8000-000000000001:0"',
          },
        },
      );
    }
  });
