  expect(new Headers(puts[1][1]?.headers).get("X-CSRF-TOKEN")).toBe(
    "new-token",
  );
  expect(new Headers(puts[1][1]?.headers).get("If-Match")).toBe(absentTag);
  expect(
    fetcher.mock.calls.filter(
      ([url, options]) => String(url) === api && options?.method !== "PUT",
    ),
  ).toHaveLength(1);
});
